/** Keystroke logs, the input of the simulator: one event per line. */

/** One event of a keystroke log; ``line`` is its 1-based line number. */
export type KeystrokeEvent =
  | { kind: "type"; time: number; text: string; line: number }
  | { kind: "close"; time: number; line: number };

/** A log line that cannot be read. */
export class KeystrokeError extends Error {
  line: number;

  constructor(line: number, message: string) {
    super(`line ${line}: ${message}`);
    this.name = "KeystrokeError";
    this.line = line;
  }
}

const TYPE = /^(\d+) type(?: (.*))?$/;
const CLOSE = /^(\d+) close$/;

/**
 * Read a keystroke log. ``TIME type TEXT`` is an edit (TEXT, which may be empty, is the
 * whole text of the field after the edit) and ``TIME close`` closes the note; TIME is
 * whole milliseconds from the start and must not go down. Blank lines and lines
 * starting with "#" are skipped. Throws a KeystrokeError naming the first bad line.
 */
export function parseKeystrokes(text: string): KeystrokeEvent[] {
  const events: KeystrokeEvent[] = [];
  let last = 0;
  text.split("\n").forEach((raw, index) => {
    const line = index + 1;
    const content = raw.endsWith("\r") ? raw.slice(0, -1) : raw;
    if (content.trim() === "" || content.trimStart().startsWith("#")) {
      return;
    }
    const typed = TYPE.exec(content);
    const closed = typed === null ? CLOSE.exec(content) : null;
    const match = typed ?? closed;
    if (match === null) {
      throw new KeystrokeError(
        line,
        `expected "TIME type TEXT" or "TIME close", got ${JSON.stringify(content)}`,
      );
    }
    const time = Number(match[1]);
    if (!Number.isSafeInteger(time)) {
      throw new KeystrokeError(line, `time ${match[1]} is too large`);
    }
    if (time < last) {
      throw new KeystrokeError(line, `time ${time} is earlier than the time before it (${last})`);
    }
    last = time;
    if (typed !== null) {
      events.push({ kind: "type", time, text: typed[2] ?? "", line });
    } else {
      events.push({ kind: "close", time, line });
    }
  });
  return events;
}

/** Replaying a keystroke log through the autosave of one field, on a manual clock. */

import type { AutosaveDelays, Draft, NoteField } from "./autosave.ts";
import { createAutosave } from "./autosave.ts";
import type { KeystrokeEvent } from "./keystrokes.ts";
import { ManualScheduler } from "./scheduler.ts";

/** A saved draft and the time it was saved. */
export interface SavedDraft {
  time: number;
  draft: Draft;
}

/** What happened when a log was replayed. */
export interface Simulation {
  field: NoteField;
  delays: Readonly<AutosaveDelays>;
  edits: number;
  saves: SavedDraft[];
}

/** Options of simulate. */
export interface SimulateOptions {
  /** The field whose autosave is replayed (default body). */
  field?: NoteField;
  /** Delays to try instead of the field's. */
  delays?: AutosaveDelays;
}

/**
 * Replay ``events``: time moves to each event in turn, edits go to the autosave, and a
 * close flushes it. After the last event, time runs on until every waiting draft is
 * saved.
 */
export function simulate(events: readonly KeystrokeEvent[], options: SimulateOptions = {}): Simulation {
  const scheduler = new ManualScheduler();
  const field = options.field ?? "body";
  const saves: SavedDraft[] = [];
  const autosave = createAutosave({
    noteId: "simulated",
    field,
    save: (draft) => saves.push({ time: scheduler.now(), draft }),
    delays: options.delays,
    scheduler,
  });
  let edits = 0;
  for (const event of events) {
    scheduler.advanceTo(event.time);
    if (event.kind === "type") {
      autosave.edit(event.text);
      edits += 1;
    } else {
      autosave.flush();
    }
  }
  scheduler.runAll();
  return { field, delays: autosave.delays, edits, saves };
}

function count(n: number, noun: string): string {
  return `${n} ${noun}${n === 1 ? "" : "s"}`;
}

/** The simulator's report: the delays, one line per saved draft, and a summary. */
export function formatSimulation(result: Simulation): string {
  const { wait, maxWait } = result.delays;
  const delays = maxWait === undefined ? `wait ${wait} ms` : `wait ${wait} ms, max wait ${maxWait} ms`;
  const lines = [`autosave of ${result.field} (${delays})`];
  for (const { time, draft } of result.saves) {
    lines.push(`${String(time).padStart(6)} ms  saved r${draft.revision} ${JSON.stringify(draft.text)}`);
  }
  lines.push(`${count(result.edits, "edit")}, ${count(result.saves.length, "save")}`);
  return `${lines.join("\n")}\n`;
}

/**
 * Clocks and timers for the timing helpers. Everything that waits takes a Scheduler,
 * so tests and the simulator can move time by hand with ManualScheduler.
 */

/** A handle returned by Scheduler.setTimeout. */
export type TimerHandle = unknown;

/** Where the timing helpers read the time and set timers (milliseconds). */
export interface Scheduler {
  /** The current time in milliseconds. */
  now(): number;
  /** Run ``callback`` once, ``delay`` milliseconds from now. */
  setTimeout(callback: () => void, delay: number): TimerHandle;
  /** Cancel a timer that has not run yet; a timer that already ran is ignored. */
  clearTimeout(handle: TimerHandle): void;
}

/** The real clock and timers. */
export const systemScheduler: Scheduler = {
  now: () => performance.now(),
  setTimeout: (callback, delay) => globalThis.setTimeout(callback, delay),
  clearTimeout: (handle) => {
    globalThis.clearTimeout(handle as ReturnType<typeof globalThis.setTimeout>);
  },
};

/** Check a delay: a finite number of milliseconds of at least 0 (RangeError otherwise). */
export function checkDelay(name: string, value: number): void {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    throw new RangeError(`${name} must be a number of milliseconds of at least 0, got ${String(value)}`);
  }
}

interface Timer {
  id: number;
  at: number;
  callback: () => void;
}

/**
 * A scheduler whose time moves only when advance or advanceTo is called. Timers run in
 * the order they are due, and timers due at the same time in the order they were set.
 * A timer set while time moves runs in the same move when it comes due.
 */
export class ManualScheduler implements Scheduler {
  #now: number;
  #nextId = 1;
  #timers: Timer[] = [];

  constructor(start = 0) {
    this.#now = start;
  }

  now(): number {
    return this.#now;
  }

  setTimeout(callback: () => void, delay: number): TimerHandle {
    const id = this.#nextId;
    this.#nextId += 1;
    this.#timers.push({ id, at: this.#now + Math.max(0, delay), callback });
    return id;
  }

  clearTimeout(handle: TimerHandle): void {
    this.#timers = this.#timers.filter((timer) => timer.id !== handle);
  }

  /** How many timers are waiting to run. */
  pending(): number {
    return this.#timers.length;
  }

  /** Move time forward by ``ms`` milliseconds, running every timer that comes due. */
  advance(ms: number): void {
    if (!(ms >= 0)) {
      throw new RangeError(`cannot move time by ${ms} ms`);
    }
    this.advanceTo(this.#now + ms);
  }

  /** Move time forward to ``time``, running every timer due at or before it. */
  advanceTo(time: number): void {
    if (!(time >= this.#now)) {
      throw new RangeError(`cannot move time back from ${this.#now} to ${time}`);
    }
    for (let next = this.#nextDue(time); next !== undefined; next = this.#nextDue(time)) {
      const timer = next;
      this.#timers = this.#timers.filter((other) => other !== timer);
      this.#now = timer.at;
      timer.callback();
    }
    this.#now = time;
  }

  /** Run timers until none is left; throws after ``limit`` moves (timers that keep coming). */
  runAll(limit = 10_000): void {
    for (let moves = 0; this.#timers.length > 0; moves += 1) {
      if (moves >= limit) {
        throw new Error(`timers are still waiting after ${limit} moves`);
      }
      const next = this.#nextDue(Number.POSITIVE_INFINITY);
      if (next !== undefined) {
        this.advanceTo(next.at);
      }
    }
  }

  #nextDue(time: number): Timer | undefined {
    let best: Timer | undefined;
    for (const timer of this.#timers) {
      if (timer.at > time) {
        continue;
      }
      if (best === undefined || timer.at < best.at || (timer.at === best.at && timer.id < best.id)) {
        best = timer;
      }
    }
    return best;
  }
}

